import math

def cosine_lr(step, total_steps, max_lr, min_lr=0.0):
    progress = min(max(step / total_steps, 0.0), 1.0)
    return min_lr + 0.5 * (max_lr - min_lr) * (1 + math.cos(math.pi * progress))

for step in (0, 250, 500, 750, 1000):
    print(step, cosine_lr(step, 1000, 1e-3, 1e-4))

import math

def warmup_cosine_lr(step, warmup_steps, total_steps, max_lr, min_lr=0.0):
    if total_steps <= warmup_steps:
        raise ValueError("total_steps must exceed warmup_steps")
    if step < warmup_steps:
        return max_lr * max(step, 0) / max(1, warmup_steps)
    progress = min(max((step - warmup_steps) / (total_steps - warmup_steps), 0.0), 1.0)
    return min_lr + 0.5 * (max_lr - min_lr) * (1 + math.cos(math.pi * progress))

print([warmup_cosine_lr(s, 100, 1000, 3e-4, 3e-5) for s in (0, 50, 100, 500, 1000)])
